import{_ as t,o as n,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Sequence Flow — Create Agency with Personal & Business Mode","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/personal-agency-transition/sequence-flow.md","filePath":"feature/agency-workspace/personal-agency-transition/sequence-flow.md"}'),a={name:"feature/agency-workspace/personal-agency-transition/sequence-flow.md"};function s(l,e,c,d,r,h){return n(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="sequence-flow-—-create-agency-with-personal-business-mode" tabindex="-1">Sequence Flow — Create Agency with Personal &amp; Business Mode <a class="header-anchor" href="#sequence-flow-—-create-agency-with-personal-business-mode" aria-label="Permalink to &quot;Sequence Flow — Create Agency with Personal &amp; Business Mode&quot;">​</a></h1><p>&gt; Tài liệu đồng hành với <code>report3_spec.md</code> và <code>report4_sequence.puml</code> (FR 3.4.3.B). Mô tả chi tiết từng bước tương tác: Actor → Action → System Step theo đúng mô hình kiến trúc BrandHub.</p><h2 id="cac-thuc-the-tham-gia-participants" tabindex="-1">Các Thực Thể Tham Gia (Participants) <a class="header-anchor" href="#cac-thuc-the-tham-gia-participants" aria-label="Permalink to &quot;Các Thực Thể Tham Gia (Participants)&quot;">​</a></h2><ul><li><strong>User</strong> — Người dùng đã đăng nhập (JWT token hợp lệ).</li><li><strong>Client (Frontend)</strong> — Ứng dụng Web Dashboard (<code>brandhub-web-dashboard</code>).</li><li><strong>Gateway</strong> — API Gateway (<code>brandhub-api-gateway</code> port 8080).</li><li><strong>System (Backend)</strong> — Core service (<code>brandhub-business-service</code> port 8081).</li><li><strong>Database</strong> — PostgreSQL (<code>agencies</code>, <code>agency_members</code>, <code>workspaces</code>, <code>workspace_members</code>).</li></ul><hr><h2 id="luong-a-tao-agency-ca-nhan-personal-mode-—-tu-đong-kich-hoat-workspace" tabindex="-1">Luồng A: Tạo Agency Cá Nhân (Personal Mode — Tự Động Kích Hoạt Workspace) <a class="header-anchor" href="#luong-a-tao-agency-ca-nhan-personal-mode-—-tu-đong-kich-hoat-workspace" aria-label="Permalink to &quot;Luồng A: Tạo Agency Cá Nhân (Personal Mode — Tự Động Kích Hoạt Workspace)&quot;">​</a></h2><ol><li><strong>User → Client</strong>: Người dùng mở màn hình Tạo Agency (<code>/agency/create</code>), chọn mục đích <strong>&quot;Cá nhân&quot; (<code>PERSONAL</code>)</strong>.</li><li><strong>Client</strong>: Form tự động thích ứng: <ul><li>Ẩn trường quy mô nhân sự <code>companySize</code>.</li><li>Đổi nhãn thành &quot;Tên thương hiệu cá nhân / Kênh của bạn&quot;.</li><li>Đổi nút submit thành &quot;Bắt đầu sáng tạo ngay ✨&quot;.</li></ul></li><li><strong>User → Client</strong>: Nhập tên thương hiệu (bắt buộc) và các thông tin nhận diện tùy chọn (logo, màu chủ đạo, mô tả, MXH) -&gt; Nhấn Submit.</li><li><strong>Client → Gateway → System</strong>: Gửi <code>POST /api/v1/agencies</code> với payload:<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bếp Nhà Mai&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PERSONAL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;category&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FNB&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;brandColor&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#f05a28&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;logoIcon&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Utensils&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Kênh ẩm thực gia đình&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><strong>System (Validation &amp; Transaction)</strong>: <ul><li>Xác thực: <code>name</code> không rỗng, <code>brandColor</code> &lt;= 9 ký tự, <code>tagline</code> &lt;= 140 ký tự.</li><li>Bắt đầu transaction <code>@Transactional</code>.</li></ul></li><li><strong>System → Database (Tạo Agency &amp; Owner)</strong>: <ul><li>Lưu bản ghi <code>agencies</code> với <code>type = &#39;PERSONAL&#39;</code>, <code>status = &#39;ACTIVE&#39;</code>, <code>owner_id = currentUser.id</code>.</li><li>Lưu bản ghi <code>agency_members</code> với <code>agency_id</code>, <code>user_id</code>, <code>role = &#39;OWNER&#39;</code>.</li></ul></li><li><strong>System → Database (Auto-provision Workspace)</strong>: <ul><li>Do <code>type == &#39;PERSONAL&#39;</code>, hệ thống tự động khởi tạo bản ghi <code>workspaces</code>: <ul><li><code>agency_id</code>: id của Agency vừa tạo ở bước 6.</li><li><code>name</code>: &quot;Bếp Nhà Mai&quot; (kế thừa tên).</li><li><code>created_by</code>: <code>currentUser.id</code>.</li><li><code>brand_color</code>, <code>logo_icon</code>, <code>description</code>: kế thừa từ Agency.</li><li><code>timezone_config</code>: &quot;Asia/Ho_Chi_Minh&quot;.</li><li><code>settings</code>: &quot;{}&quot;.</li></ul></li><li>Lưu bản ghi <code>workspace_members</code>: <ul><li><code>workspace_id</code>: id của Workspace vừa tạo.</li><li><code>user_id</code>: <code>currentUser.id</code>.</li><li><code>role</code>: <code>MANAGER</code>.</li><li><code>is_active</code>: <code>true</code>.</li></ul></li></ul></li><li><strong>System → Gateway → Client</strong>: Trả về <code>201 Created</code> kèm <code>AgencyResponse</code> có <code>defaultWorkspaceId = personalWorkspace.id</code>.</li><li><strong>Client (State Update &amp; Navigation)</strong>: <ul><li>Cập nhật <code>agencyStore</code>: gán <code>currentAgencyId</code>.</li><li>Cập nhật <code>workspaceStore</code>: gán <code>currentWorkspace = personalWorkspace</code>.</li><li>Hiển thị Toast thông báo thành công.</li><li><strong>Chuyển hướng lập tức sang <code>/workspaces/{defaultWorkspaceId}/dashboard</code></strong>.</li></ul></li><li><strong>Client UI State (Personal Mode Activated)</strong>: <ul><li>Sidebar ẩn hoàn toàn các mục: Khách hàng (<code>/clients</code>), Hồ sơ khách hàng (<code>/client-profiles</code>), Lời mời khách hàng (<code>/client/invitations</code>), Cổng khách hàng (<code>/portal</code>), Phân quyền (<code>/agency/:id/roles</code>).</li><li>Các công cụ Sáng tạo nội dung (Viết bài, Lịch, Thư viện, Đăng bài) được mở sẵn sàng để sử dụng.</li></ul></li></ol><hr><h2 id="luong-b-tao-agency-doanh-nghiep-business-mode-—-luong-chuan" tabindex="-1">Luồng B: Tạo Agency Doanh Nghiệp (Business Mode — Luồng Chuẩn) <a class="header-anchor" href="#luong-b-tao-agency-doanh-nghiep-business-mode-—-luong-chuan" aria-label="Permalink to &quot;Luồng B: Tạo Agency Doanh Nghiệp (Business Mode — Luồng Chuẩn)&quot;">​</a></h2><ol><li><strong>User → Client</strong>: Người dùng chọn mục đích <strong>&quot;Doanh nghiệp&quot; (<code>BUSINESS</code>)</strong>.</li><li><strong>Client</strong>: Form hiển thị đầy đủ các trường doanh nghiệp: Quy mô công ty (<code>companySize</code>), Website, Thông tin liên hệ.</li><li><strong>User → Client</strong>: Nhập thông tin và bấm &quot;Tạo Agency&quot;.</li><li><strong>Client → Gateway → System</strong>: Gửi <code>POST /api/v1/agencies</code> với <code>type = &quot;BUSINESS&quot;</code>.</li><li><strong>System → Database</strong>: Lưu bản ghi <code>agencies</code> (<code>type = &#39;BUSINESS&#39;</code>) và <code>agency_members</code> (<code>OWNER</code>). <strong>Không</strong> tự động tạo Workspace.</li><li><strong>System → Client</strong>: Trả về <code>201 Created</code> (<code>defaultWorkspaceId = null</code>).</li><li><strong>Client</strong>: Chuyển hướng người dùng về trang chi tiết Agency <code>/agency/{agencyId}</code>.</li></ol><hr><h2 id="bang-xu-ly-cac-truong-hop-loi-error-paths" tabindex="-1">Bảng Xử Lý Các Trường Hợp Lỗi (Error Paths) <a class="header-anchor" href="#bang-xu-ly-cac-truong-hop-loi-error-paths" aria-label="Permalink to &quot;Bảng Xử Lý Các Trường Hợp Lỗi (Error Paths)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Giai đoạn</th><th style="text-align:left;">Điều kiện lỗi</th><th style="text-align:center;">HTTP Status</th><th style="text-align:left;">Error Code</th><th style="text-align:left;">Xử lý giao diện / Hệ thống</th></tr></thead><tbody><tr><td style="text-align:left;">Client Validate</td><td style="text-align:left;">Tên để trống</td><td style="text-align:center;">N/A</td><td style="text-align:left;">MSG02</td><td style="text-align:left;">Báo lỗi đỏ dưới ô input &quot;Tên không được để trống&quot;, chặn submit.</td></tr><tr><td style="text-align:left;">Server Validate</td><td style="text-align:left;">Tên toàn khoảng trắng</td><td style="text-align:center;">400</td><td style="text-align:left;"><code>VALIDATION_ERROR</code></td><td style="text-align:left;">GlobalExceptionHandler bắt lỗi, trả về danh sách field error.</td></tr><tr><td style="text-align:left;">Server Validate</td><td style="text-align:left;">Mã màu hoặc tagline vượt quá độ dài</td><td style="text-align:center;">400</td><td style="text-align:left;"><code>VALIDATION_ERROR</code></td><td style="text-align:left;">Báo lỗi trường <code>brandColor</code> hoặc <code>tagline</code>.</td></tr><tr><td style="text-align:left;">Xác thực phiên</td><td style="text-align:left;">Không có Token hoặc Token hết hạn</td><td style="text-align:center;">401</td><td style="text-align:left;"><code>UNAUTHORIZED</code></td><td style="text-align:left;">Chuyển hướng về <code>/login</code>, hiển thị toast MSG22.</td></tr><tr><td style="text-align:left;">Database Write</td><td style="text-align:left;">Lỗi lưu Workspace hoặc gán Member</td><td style="text-align:center;">500</td><td style="text-align:left;"><code>INTERNAL_SERVER_ERROR</code></td><td style="text-align:left;">Transaction tự động rollback toàn bộ, không tạo Agency mồ côi.</td></tr></tbody></table>`,13)])])}const u=t(a,[["render",s]]);export{p as __pageData,u as default};
